import{_ as t,o as i,c as o,a2 as s,j as n}from"./chunks/framework.BPyF_sP4.js";const e="/ai-agent-handbook/assets/image-005.1QyWZXFI.png",p="/ai-agent-handbook/assets/image-006.HTv-J0tp.png",l="/ai-agent-handbook/assets/image-007.BdyRKZo6.png",r="/ai-agent-handbook/assets/image-008.pdkZ2KJp.png",h="/ai-agent-handbook/assets/image-009.Ys0QC1jh.png",q=JSON.parse('{"title":"哔哩哔哩构建全域内容洞察的实践","description":"","frontmatter":{"title":"哔哩哔哩构建全域内容洞察的实践","bookSource":"06-case-study/第28章 客户、销售与运营/哔哩哔哩构建全域内容洞察的实践.md","bookPart":"实践篇","bookChapter":28,"readingMinutes":6,"prev":{"text":"会计师事务所信永中和的办公提效探索","link":"/cases/chapter-28/shinewing.html"},"next":{"text":"运营分析 Data Agent 实践","link":"/cases/chapter-28/data-agent.html"},"editLink":true},"headers":[],"relativePath":"cases/chapter-28/bilibili.md","filePath":"06-case-study/第28章 客户、销售与运营/哔哩哔哩构建全域内容洞察的实践.md","lastUpdated":1790179803000}'),g={name:"cases/chapter-28/bilibili.md"};function d(c,a,k,_,u,B){return i(),o("div",null,[...a[0]||(a[0]=[s('<h1 id="哔哩哔哩构建全域内容洞察的实践" tabindex="-1">哔哩哔哩构建全域内容洞察的实践 <a class="header-anchor" href="#哔哩哔哩构建全域内容洞察的实践" aria-label="Permalink to &quot;哔哩哔哩构建全域内容洞察的实践&quot;">​</a></h1><h2 id="一、客户背景" tabindex="-1">一、客户背景 <a class="header-anchor" href="#一、客户背景" aria-label="Permalink to &quot;一、客户背景&quot;">​</a></h2><p>哔哩哔哩（B站）是国内领先的文化社区和视频平台。平台内容生态高度多元化，涵盖视频、图文、直播、音频、互动内容、搜索、动态等多种体裁。作为以“内容种草”为核心心智的平台，B站已成为品牌营销的重要阵地，尤其在汽车、3C数码、美妆、快消、教育培训、游戏等行业具备显著影响力。</p><h2 id="二、业务场景与核心痛点" tabindex="-1">二、业务场景与核心痛点 <a class="header-anchor" href="#二、业务场景与核心痛点" aria-label="Permalink to &quot;二、业务场景与核心痛点&quot;">​</a></h2><p>与传统电商平台不同，B站用户的消费决策往往源于内容互动所形成的品牌认知与兴趣积累，而非站内直接转化。这一特点对营销效果评估提出了更高要求。为此，平台基于经过去标识化、匿名化处理的海量公开互动数据，开展群体层面的数据趋势分析，以支持内容生态优化与商业服务能力的持续提升。例如，通过分析洞察辅助评估品牌内容的传播广度与用户反馈方向，为广告主提供更科学的效果参考。</p><p><img src="'+e+'" alt="image.png" loading="lazy"></p><p>B站内容平台营销商业化路径</p><p>B站商业化团队在服务品牌客户过程中，面临三大核心挑战：</p><ol><li><p><strong>营销效果难以量化</strong>：品牌在B站投放内容（如UP主种草视频）后，缺乏有效手段衡量用户群体是否被“种草”。例如，某汽车品牌发布新车测评视频后，需从去标识化的互动内容中识别用户群体对续航、外观、价格等属性的评价，以评估内容传播效果。</p></li><li><p><strong>内容资产难以结构化</strong>：B站内容体裁丰富、语义复杂，视频中包含大量视觉、语音、文本信息，互动区则充斥高信息密度的长文本。传统关键词匹配或规则引擎难以准确提取商业实体（如品牌、类目、SPU）及其关联语义。</p></li><li><p><strong>营销策略缺乏数据支撑</strong>：品牌希望基于B站真实讨论内容，反向指导新品定义、传播策略与创意方向。例如，某美妆品牌需了解用户群体在讨论粉底液时最关注“持妆度”“遮瑕力”还是“肤感”，但缺乏系统性内容洞察工具。</p></li></ol><p>为解决上述问题，B站商业化数据科学团队联合阿里云，构建了一套面向全域内容的结构化洞察框架，实现从“内容感知”到“商业洞察”的数据闭环。</p><h2 id="三、解决方案-大模型-小模型-协同的全域内容洞察新框架" tabindex="-1">三、解决方案：“大模型+小模型”协同的全域内容洞察新框架 <a class="header-anchor" href="#三、解决方案-大模型-小模型-协同的全域内容洞察新框架" aria-label="Permalink to &quot;三、解决方案：“大模型+小模型”协同的全域内容洞察新框架&quot;">​</a></h2><p>PolarDB for AI 是阿里云云原生数据库 PolarDB 内部的分布式机器学习组件，支持在数据不出库的前提下，高效调用轻量化小模型进行实时推理，同时可联动通义千问等大模型处理复杂语义任务，实现大模型与小模型协同一体化架构。</p><p><img src="'+p+'" alt="image.png" loading="lazy"></p><p>PolarDB for AI一站式方案</p><ul><li><p>PolarDB for AI 可以通过调用通义千问大模型，对经过去标识化、匿名化处理的用户互动内容进行批量分析，辅助洞察群体层面的兴趣趋势与反馈倾向，为产品优化与内容策略提供数据支持。</p></li><li><p>PolarDB for AI 通过定制化的电商领域大模型，结合阿里电商领域的商品知识图谱，大大提升B站对类目、品牌、SPU等多个标签的识别能力，实现品牌高精准匹配，促进内容资产结构化。</p></li></ul><p><img src="'+l+'" alt="image.png" loading="lazy"></p><p>B站全域内容洞察矩阵</p><p>B站采用“大模型+小模型”融合的技术路径，依托 DeepSeek、阿里云通义千问（Qwen）系列大模型、B站自研的Index模型与 PolarDB for AI 能力，构建覆盖M×N矩阵的全域内容洞察体系，M为商业化标签维度，N为内容体裁维度。</p><p>整体技术架构分为三层：</p><ul><li><p><strong>AI 基建层</strong>：基于阿里云百炼平台、PAI、GPU资源及B站自研Agent平台，提供模型训练、推理与调度能力。</p></li><li><p><strong>数据与模型层</strong>：结合通用大模型（如 Qwen、Qwen-VL、Qwen-Audio）与 <strong>PolarDB for AI</strong>提供的领域小模型（经 SFT、强化学习微调），实现高效、低成本的内容洞察。</p></li><li><p><strong>应用服务层</strong>：通过 PolarDB for AI 节点，提供模型算子能力，实现“数据不出库”的高效挂靠与推理，且提供稳定独享的模型实时在线服务能力。</p></li></ul><p>该方案兼顾效果与成本：通用大模型用于标签体系挖掘与复杂语义分析，领域小模型则在特定任务（如实体抽取）上实现更高精度与更低延迟。</p><h2 id="四、关键技术实现与难点突破" tabindex="-1">四、关键技术实现与难点突破 <a class="header-anchor" href="#四、关键技术实现与难点突破" aria-label="Permalink to &quot;四、关键技术实现与难点突破&quot;">​</a></h2><h4 id="_1、视频稿件内容提取-从非结构化到结构化" tabindex="-1">1、视频稿件内容提取：从非结构化到结构化 <a class="header-anchor" href="#_1、视频稿件内容提取-从非结构化到结构化" aria-label="Permalink to &quot;1、视频稿件内容提取：从非结构化到结构化&quot;">​</a></h4><p><img src="'+r+`" alt="image.png" loading="lazy"></p><p>视频内容提取过程</p><p>视频是B站核心内容载体，但其信息分散于画面、语音与字幕中。B 站采用多模态融合策略：</p><ul><li><p><strong>中间层构建</strong>：通过 ASR（语音转文本）与关键帧 OCR（图像文字识别）提取原始文本，再利用 Qwen-VL、Qwen-Audio 等多模态大模型生成语义中间表示。</p></li><li><p><strong>CPV体系构建</strong>：基于大模型挖掘与行业维护，建立“类目-属性-属性值”体系。例如，识别出视频中“相机”类目下的“防抖技术”属性及其值“IBIS”。</p></li><li><p><strong>实体三元组抽取与挂靠</strong>：通过大模型抽取&lt;类目, 品牌, SPU&gt;三元组，但原始抽取结果存在与标准产品库里的命名不一致的问题（如“尼康Z5” vs “尼康Z5微单相机”）。</p></li></ul><p><strong>技术难点</strong>：如何将非标准化抽取结果精准挂靠至标准产品库？</p><p><strong>解决方案</strong>：B站与阿里云PolarDB团队合作，在<strong>PolarDB for AI</strong>节点中部署定制化挂靠模型。通过SQL，在数据库内直接调用精调后的大模型进行实体对齐。例如，我们来预测一个稿件的类目。执行如下SQL：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/*polar4ai*/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> </span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> FROM</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> PREDICT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  MODEL _polar4ai_cpv_agent, </span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  SELECT</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;商品名称&quot;:&quot;尼康Z5&quot;,&quot;品牌名称&quot;:&quot;尼康&quot;,&quot;类目属性模板&quot;:{&quot;类目&quot;:&quot;&quot;},&quot;类目属性限定&quot;:{&quot;类目&quot;:[&quot;数码-摄影摄像-传统相机-相机&quot;,&quot;数码-数码配件&quot;,...]}}&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WITH</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ();</span></span></code></pre></div>`,30),n("p",{"类目：数码-摄影摄像-传统相机-相机":""},"得到",-1),s('<p>该方案实现“数据不出库”的高并发挂靠，解决抽取结果与标准产品命名的一致性问题，既保障数据安全，又显著降低工程复杂度。同时，结合 BGE+RoBERTa 等 NLP 模型进行匹配，进一步提升挂靠准确率。</p><h4 id="_2、互动内容分析-从海量数据中挖掘高价值线索" tabindex="-1">2、互动内容分析：从海量数据中挖掘高价值线索 <a class="header-anchor" href="#_2、互动内容分析-从海量数据中挖掘高价值线索" aria-label="Permalink to &quot;2、互动内容分析：从海量数据中挖掘高价值线索&quot;">​</a></h4><p><img src="'+h+'" alt="image.png" loading="lazy"></p><p>互动内容分析过程</p><p>B站评论区信息密度很高，但90%以上为非商业化内容。直接使用大模型全量处理成本高昂。</p><p>**技术难点：**如何在成本可控的前提下，利用匿名化互动数据实现多实体群体反馈的细粒度分析，支撑内容与商业服务的持续优化？</p><p><strong>解决方案</strong>：采用“过滤-分析-挖掘”三级流水线：</p><ul><li><p><strong>第一级：商业化过滤</strong>：使用轻量级 NLP 模型，如 BGE+BiLSTM 模型快速筛除无关内容，仅保留可能涉及品牌、产品讨论的内容。</p></li><li><p><strong>第二级：实体与语义关联分析</strong>：对过滤后文本，利用 <strong>PolarDB for AI 提供的商品大模型</strong>识别类目、品牌、SPU，并建立不同实体间的语义关联关系。</p></li><li><p><strong>第三级：意图与属性挖掘</strong>：进一步识别“种草”“购买意愿”等高阶语义，并提取用户群体关注的具体属性（如“续航达成率高”“价格贵”），形成结构化洞察。</p></li></ul><h2 id="五、总结" tabindex="-1">五、总结 <a class="header-anchor" href="#五、总结" aria-label="Permalink to &quot;五、总结&quot;">​</a></h2><p>通过与阿里云通义千问大模型及 PolarDB for AI 的深度协同，B 站成功构建了一套高效、可扩展的全域内容洞察体系。该体系不仅解决了品牌营销效果度量难、内容资产结构化难等核心痛点，更将 B 站独特的社区公开互动数据转化为可行动的商业洞察，显著提升了广告主的投放确定性与 ROI。目前，该全域内容洞察体系已应用于 B 站的哔哩指数、花火平台 AI 选 UP 主、哔哩必达洞察报告、引力计划爆文投放、经营号线索挖掘及品牌广告搜索词包等商业化场景，实现从内容洞察到营销转化的全链路提效。未来，B 站将持续优化模型能力，拓展至更多内容体裁与商业场景，进一步释放内容平台的营销价值。</p>',10)])])}const P=t(g,[["render",d]]);export{q as __pageData,P as default};
